{"tool": "write", "path": "tests/test_export.py", "content": "import unittest

from reports.export import export_csv


class ExportCsvTest(unittest.TestCase):
    def test_basic(self):
        out = export_csv(
            [{"a": 1, "b": "x"}, {"a": 2, "b": "y"}],
            ["a", "b"],
        )
        self.assertEqual(out, "a,b\r\n1,x\r\n2,y\r\n")

    def test_quoting_and_doubling(self):
        out = export_csv(
            [{"a": 'he said "hi"', "b": "line1\nline2", "c": "x,y"}],
            ["a", "b", "c"],
        )
        self.assertEqual(
            out, 'a,b,c\r\n"he said ""hi""","line1\nline2","x,y"\r\n'
        )

    def test_missing_and_none(self):
        out = export_csv([{"a": None}], ["a", "b"])
        self.assertEqual(out, "a,b\r\n,\r\n")

    def test_empty_rows_and_columns(self):
        self.assertEqual(export_csv([], []), "\r\n")
        self.assertEqual(export_csv([], ["a"]), "a\r\n")
        self.assertEqual(export_csv([{}, {}], []), "\r\n\r\n\r\n")

    def test_generators(self):
        out = export_csv(iter([{"a": 1}]), iter(["a"]))
        self.assertEqual(out, "a\r\n1\r\n")

    def test_reject_duplicates_and_nonstrings(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])
        with self.assertRaises(ValueError):
            export_csv([], [1])

    def test_inputs_not_mutated(self):
        rows = [{"a": 1}]
        cols = ["a"]
        export_csv(rows, cols)
        self.assertEqual(rows, [{"a": 1}])
        self.assertEqual(cols, ["a"])

    def test_unicode_and_embedded_cr(self):
        out = export_csv([{"a": "héllo\rworld"}], ["a"])
        self.assertEqual(out, 'a\r\n"héllo\rworld"\r\n')


if __name__ == "__main__":
    unittest.main()
